export const FORENSICS_QUESTIONS = {
  facil: [
    ["¿Qué principio establece que la evidencia digital debe recopilarse comenzando por los datos más volátiles?", ["Principio de Locard aplicado a evidencia digital", "Orden de volatilidad (RFC 3227)", "Regla de la mejor evidencia según NIST SP 800-86", "Jerarquía de preservación de ISO 27037"], 1, "RFC 3227 establece que se debe recopilar primero la evidencia más volátil (registros CPU, RAM) antes que la menos volátil (discos, medios de archivo)."],
    ["¿Qué es una imagen forense?", ["Una captura del tráfico de red en formato PCAP del equipo investigado", "Una copia bit a bit de un medio de almacenamiento que incluye todo el contenido del disco", "Un respaldo verificado del sistema de archivos activo con sus metadatos", "Una exportación selectiva de archivos relevantes con hashes de verificación"], 1, "Una imagen forense es una copia exacta, sector por sector, del medio original que preserva toda la información incluyendo espacio no asignado y datos residuales."],
    ["¿Qué función cumple un hash criptográfico en la investigación forense?", ["Cifrar la evidencia para garantizar su confidencialidad durante el transporte", "Autenticar al investigador que realizó la adquisición de la imagen", "Verificar que la evidencia no fue alterada desde su adquisición", "Generar una firma digital vinculada a la identidad del perito"], 2, "Los hashes como SHA-256 generan una huella única que permite demostrar que la evidencia no fue alterada desde su adquisición."],
    ["¿Qué es la cadena de custodia?", ["La secuencia documentada de herramientas y métodos aplicados durante el análisis", "El registro documentado de quién tuvo acceso a la evidencia, cuándo y en qué condiciones", "El orden en que se procesan las fuentes de evidencia según su prioridad probatoria", "El proceso de validación de las herramientas forenses antes de su uso en un caso"], 1, "La cadena de custodia documenta toda transferencia, acceso y almacenamiento de la evidencia para garantizar su admisibilidad legal."],
    ["¿Qué tipo de dato es el más volátil según RFC 3227?", ["Tablas de enrutamiento, caché ARP y memoria principal del sistema", "Archivos temporales y sistemas de archivos virtuales montados", "Registros de CPU, caché del procesador y contadores internos", "Conexiones de red activas y estados de los sockets del kernel"], 2, "Los registros de CPU y la caché son los más volátiles y desaparecen inmediatamente al cortar la alimentación o cambiar el contexto del procesador."],
    ["¿Para qué sirve un bloqueador de escritura en forense digital?", ["Para verificar la integridad de los hashes calculados durante la adquisición", "Para aislar eléctricamente el medio y prevenir daños por descarga estática", "Para impedir modificaciones en el medio original durante el proceso de adquisición", "Para garantizar que la imagen forense resultante sea una copia verificable"], 2, "Un bloqueador de escritura (write blocker) garantiza que el medio original no sea alterado durante la creación de la imagen forense."],
    ["¿Qué norma ISO proporciona directrices específicas para la identificación, recolección, adquisición y preservación de evidencia digital?", ["ISO 27042 — Análisis e interpretación de evidencia digital", "ISO 27041 — Aseguramiento de métodos de investigación", "ISO 27037 — Manejo inicial de evidencia digital", "ISO 27043 — Principios y procesos de investigación de incidentes"], 2, "ISO/IEC 27037 define las pautas para el manejo inicial de evidencia digital, incluyendo roles como DEFR y DES."],
    ["Según ISO 27037, ¿qué rol corresponde a la persona autorizada para actuar primero en la escena recopilando evidencia digital?", ["DES — Digital Evidence Specialist", "DEFR — Digital Evidence First Responder", "CISO — Chief Information Security Officer asignado al caso", "SIO — Senior Investigating Officer del incidente"], 1, "El DEFR (Digital Evidence First Responder) es la persona capacitada y autorizada para realizar la primera intervención sobre evidencia digital en la escena."],
    ["¿Cuál es la diferencia principal entre una copia lógica y una imagen forense?", ["La imagen forense solo incluye sectores con datos activos; la copia lógica incluye además los metadatos del sistema", "La copia lógica solo incluye archivos visibles al sistema operativo; la imagen forense copia todo el medio bit a bit", "La imagen forense se verifica con firma digital; la copia lógica se verifica únicamente con hash", "La copia lógica mantiene la estructura de directorios original; la imagen forense la aplana en un solo contenedor"], 1, "La imagen forense captura cada sector del medio incluyendo espacio no asignado, archivos eliminados y metadatos ocultos, mientras la copia lógica solo copia archivos accesibles."],
    ["¿Qué artefactos del sistema operativo registran qué programas se ejecutaron recientemente en Windows?", ["Las entradas del registro de auditoría de seguridad y los logs de AppLocker", "Prefetch, Shimcache (AppCompatCache) y Amcache del registro y sistema de archivos", "Los logs de Windows Defender y las alertas del servicio AMSI", "Las entradas del Task Scheduler y los registros del servicio de compatibilidad de aplicaciones"], 1, "Artefactos como Prefetch, Shimcache y Amcache registran la ejecución de programas con marcas de tiempo y rutas independientemente de la política de auditoría."],
    ["¿Qué es el espacio no asignado (unallocated space) de un disco?", ["Espacio reservado por el sistema de archivos para las estructuras de metadatos como la MFT y los journals", "Sectores del disco que no están asignados a ningún archivo activo y pueden conservar datos de archivos eliminados", "Bloques defectuosos remapeados por el controlador que quedan fuera de la tabla de direcciones lógicas", "Espacio entre particiones que el sistema operativo reserva para alineación y rendimiento óptimo"], 1, "El espacio no asignado puede contener restos de archivos eliminados, particiones previas y otros datos recuperables mediante técnicas forenses como data carving."],
    ["¿Qué tipo de herramientas se utilizan para calcular hashes de verificación en el contexto forense?", ["Herramientas de análisis de red como Wireshark con módulo de verificación de integridad", "Suites forenses de indexación como Autopsy con su motor de hashing integrado", "Utilidades de hashing como sha256sum, md5sum y las funciones de verificación de FTK Imager", "Frameworks de análisis de memoria como Volatility con sus plugins de integridad de imagen"], 2, "Estas herramientas generan resúmenes criptográficos que permiten verificar que la imagen no fue modificada desde su adquisición."],
    ["¿Cuál es la primera acción recomendada al llegar a una escena con evidencia digital?", ["Aislar los equipos de la red para evitar borrado remoto o comunicación con servidores externos", "Documentar la escena mediante fotografías, notas y registrar el estado de cada equipo visible", "Capturar la memoria volátil de los equipos encendidos siguiendo el orden de volatilidad", "Identificar y etiquetar todos los medios de almacenamiento presentes en la escena"], 1, "La documentación inicial (fotografías, notas, estado de pantallas) y la seguridad de la escena son fundamentales antes de cualquier manipulación técnica."],
    ["¿Qué información almacena la tabla MFT (Master File Table) en un sistema de archivos NTFS?", ["Índices de búsqueda optimizados y la estructura jerárquica del árbol de directorios del volumen", "Un registro por cada archivo y directorio con atributos como nombre, marcas de tiempo y ubicación de datos", "Las listas de control de acceso (ACL) y los descriptores de seguridad de cada objeto del volumen", "El mapa de bloques libres, las cadenas de asignación y los metadatos de compresión de cada archivo"], 1, "La MFT de NTFS almacena un registro por cada archivo con atributos como nombre, tamaño, marcas de tiempo ($SI, $FN) y ubicación de datos en disco."],
    ["¿Qué rama del análisis forense digital se especializa en examinar capturas de paquetes y flujos de tráfico?", ["Forense de memoria volátil y análisis de procesos", "Forense de sistemas de archivos y artefactos de disco", "Forense de red y análisis de tráfico capturado", "Forense de aplicaciones web y bases de datos"], 2, "El análisis forense de red examina capturas de paquetes (PCAP), logs de flujo NetFlow/sFlow y registros de dispositivos de red para reconstruir eventos."],
    ["¿Por qué es fundamental documentar la zona horaria configurada en el sistema analizado?", ["Para determinar si el sistema fue configurado correctamente según las políticas corporativas", "Para identificar si el equipo fue trasladado geográficamente durante el período investigado", "Para correlacionar correctamente las marcas de tiempo con eventos de otras fuentes y sistemas", "Para validar la autenticidad de los logs del sistema comprobando la coherencia temporal interna"], 2, "Las marcas de tiempo sin contexto de zona horaria pueden llevar a conclusiones erróneas al correlacionar eventos entre distintos sistemas y fuentes de evidencia."],
    ["¿Qué técnica forense permite recuperar archivos eliminados buscando patrones conocidos en el medio?", ["File system recovery que reconstruye las estructuras del sistema de archivos dañadas o eliminadas", "Data carving que busca encabezados y patrones de estructura de archivo en sectores del disco", "MFT recovery que restaura las entradas eliminadas de la tabla maestra de archivos", "Journal recovery que reconstruye archivos a partir de las transacciones registradas en el $LogFile"], 1, "El data carving busca patrones de encabezados (magic numbers) y estructuras de archivo conocidas en el espacio no asignado para reconstruir archivos eliminados."],
    ["¿Qué publicación de NIST proporciona un marco para integrar técnicas forenses en la respuesta a incidentes?", ["NIST SP 800-61 — Guía de manejo de incidentes de seguridad informática", "NIST SP 800-86 — Guía para integrar técnicas forenses en respuesta a incidentes", "NIST SP 800-53 — Controles de seguridad y privacidad para sistemas de información", "NIST SP 800-88 — Directrices para la sanitización de medios"], 1, "NIST SP 800-86 proporciona un marco para incorporar capacidades forenses digitales en el proceso de respuesta a incidentes de una organización."],
    ["¿Qué tipo de información puede revelar el análisis de metadatos embebidos en un documento?", ["Las direcciones IP y puertos de red utilizados al momento de guardar el documento", "Autor, fechas de creación y modificación, software utilizado, revisiones y a veces coordenadas GPS", "Las contraseñas de las cuentas de usuario que accedieron al documento en el sistema de archivos", "Los hashes de las versiones anteriores del documento que permiten verificar cambios realizados"], 1, "Los metadatos embebidos en documentos, imágenes y otros archivos pueden revelar información valiosa sobre su origen, edición y manipulación."],
    ["¿Qué principio forense establece que todo contacto entre dos entidades produce un intercambio de material?", ["Principio de autenticidad que asegura la procedencia verificable de la evidencia digital", "Principio de intercambio de Locard que indica que toda interacción deja rastro mutuo", "Principio de reproducibilidad que requiere resultados consistentes entre investigadores", "Principio de proporcionalidad que equilibra la intrusión de la investigación con su necesidad"], 1, "El principio de intercambio de Locard establece que toda interacción deja evidencia mutua, aplicable tanto al mundo físico como al digital."],
  ],
  medio: [
    ["Según ISO 27037, ¿qué propiedad asegura que un procedimiento forense produce los mismos resultados cuando es ejecutado por diferentes investigadores en distintos entornos?", ["Repetibilidad — el mismo investigador obtiene los mismos resultados en el mismo entorno", "Auditabilidad — cada paso puede ser revisado y verificado por un tercero independiente", "Reproducibilidad — diferentes investigadores obtienen resultados equivalentes con los mismos métodos", "Justificabilidad — cada decisión tomada durante la investigación puede ser explicada y defendida"], 2, "La reproducibilidad garantiza que distintos investigadores, usando los mismos métodos y herramientas, obtengan resultados equivalentes sobre la misma evidencia. Difiere de la repetibilidad, que se refiere al mismo investigador."],
    ["¿Qué diferencia fundamental existe entre adquisición en vivo (live) y adquisición post-mortem?", ["La adquisición en vivo requiere bloqueadores de escritura por software; la post-mortem usa bloqueadores por hardware", "La adquisición en vivo se realiza con el sistema operativo en ejecución; la post-mortem trabaja sobre un sistema apagado", "La post-mortem captura memoria y disco simultáneamente; la en vivo requiere adquisiciones separadas y secuenciales", "La adquisición en vivo produce imágenes de menor integridad probatoria que las obtenidas post-mortem"], 1, "La adquisición en vivo permite capturar memoria volátil, procesos activos y conexiones de red que se pierden al apagar el equipo."],
    ["¿Qué artefactos de Windows son los más específicos para documentar qué dispositivos USB fueron conectados al equipo?", ["Event Log de seguridad con Event IDs 4663 y 4656 que registran acceso a objetos de almacenamiento removible", "Claves del registro en USBSTOR, DeviceContainers y el archivo setupapi.dev.log", "Registros de Sysmon Event ID 6 y 11 que documentan carga de drivers y creación de archivos en medios removibles", "Entradas de Amcache con los ejecutables lanzados automáticamente desde dispositivos de almacenamiento USB"], 1, "Windows registra información sobre dispositivos USB conectados en USBSTOR (serial, VID/PID, timestamps), DeviceContainers y setupapi.dev.log con marcas de tiempo de primera conexión."],
    ["¿Qué representan las marcas de tiempo MACB en el contexto del análisis forense de sistemas NTFS?", ["Las cuatro fases del proceso de manejo de evidencia: Maintain, Acquire, Classify y Backup", "Modified, Accessed, Changed (metadata en MFT) y Born (created): cuatro timestamps almacenados por NTFS", "Los cuatro métodos de adquisición definidos por NIST: Mirror, Acquire, Clone y Bitstream", "Las cuatro categorías de artefactos: Memory, Application, Configuration y Binary según GCFE"], 1, "NTFS almacena cuatro marcas de tiempo en $STANDARD_INFORMATION y $FILE_NAME que permiten reconstruir cuándo un archivo fue modificado, accedido, cambiado en metadatos y creado."],
    ["¿Qué técnica anti-forense altera deliberadamente las marcas de tiempo de los atributos $STANDARD_INFORMATION de un archivo en NTFS?", ["Timestomping", "Log tampering", "Slack space injection", "Stream manipulation"], 0, "El timestomping altera las marcas de tiempo de $STANDARD_INFORMATION usando herramientas de espacio de usuario; comparar con $FILE_NAME (gestionada por el kernel) puede revelar la manipulación."],
    ["¿Cuáles son las cuatro fases del proceso forense según NIST SP 800-86?", ["Preservación, autenticación, interpretación y presentación judicial", "Recolección, examen, análisis y reporte de los hallazgos", "Identificación, contención, erradicación y recuperación del sistema", "Preparación, detección, evaluación y documentación de la evidencia"], 1, "NIST SP 800-86 define un proceso de cuatro fases: Collection, Examination, Analysis y Reporting, cada una con entregables y consideraciones específicas."],
    ["¿Qué información forense específica puede recuperarse del análisis de la Papelera de reciclaje ($Recycle.Bin) de Windows?", ["El hash SHA-256 del archivo original y el SID del usuario que autorizó su eliminación del sistema", "La ruta completa original del archivo, la fecha y hora exacta de eliminación y el tamaño del archivo", "El contenido completo del archivo eliminado junto con el historial de todas sus modificaciones previas", "Las ACL que protegían el archivo antes de su eliminación y el método utilizado para borrarlo"], 1, "Los archivos $I de la Papelera almacenan la ruta original, la fecha de eliminación y el tamaño; los archivos $R contienen el contenido del archivo eliminado."],
    ["¿Qué artefactos de Windows documentan específicamente los archivos abiertos recientemente a través del Explorador de archivos?", ["Las entradas de Shimcache y Amcache del registro que registran compatibilidad y ejecución de programas", "Los archivos LNK (accesos directos automáticos) y las Jump Lists asociadas a aplicaciones del usuario", "Los registros de auditoría de objetos del Event Log de seguridad con Event IDs 4663 y 4656", "Las entradas de la MFT con el atributo $STANDARD_INFORMATION que registra el último acceso a cada archivo"], 1, "Los archivos LNK y las Jump Lists documentan archivos abiertos por el usuario con información como la ruta, volumen, marcas de tiempo y a veces la dirección MAC del equipo."],
    ["¿Qué es el file slack (espacio residual) de un archivo en el contexto forense?", ["El espacio reservado por el journal del sistema de archivos para registrar transacciones pendientes de confirmación", "El espacio entre el final lógico de los datos del archivo y el final del último clúster asignado al archivo", "El área de la MFT donde se almacenan los atributos residentes de archivos cuyo contenido cabe en el registro", "El espacio de padding añadido por el sistema de archivos para alinear los datos a los límites de sector"], 1, "El file slack puede contener datos residuales de archivos anteriores que ocupaban esos mismos sectores, proporcionando evidencia potencialmente recuperable."],
    ["¿Qué ventaja técnica principal ofrece el formato de imagen forense E01 (EnCase Evidence File) sobre una imagen raw (dd)?", ["Permite la adquisición en vivo del sistema sin necesidad de apagarlo ni usar bloqueador de escritura", "Integra compresión, segmentación en archivos manejables, metadatos del caso y verificación de integridad por bloques", "Soporta cifrado AES-256 obligatorio que protege la cadena de custodia sin intervención del examinador", "Incluye un índice de búsqueda de texto completo precalculado que acelera significativamente el análisis posterior"], 1, "El formato E01 añade estructura con hashes CRC por cada bloque de 64 sectores, compresión zlib opcional y campos de metadatos del caso y del examinador."],
    ["¿En qué ubicación del registro de Windows se almacena información sobre las redes Wi-Fi a las que se conectó el equipo, incluyendo fechas de conexión?", ["HKLM\\SYSTEM\\CurrentControlSet\\Services\\Tcpip\\Parameters\\Interfaces con la configuración IP de cada adaptador", "HKLM\\SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\NetworkList\\Profiles con SSID y fechas de conexión", "HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Internet Settings\\Connections con los perfiles de proxy", "HKLM\\SYSTEM\\CurrentControlSet\\Services\\NlaSvc\\Parameters\\Internet con los resultados de detección de red"], 1, "El registro NetworkList\\Profiles almacena SSID, tipo de red (pública, privada, dominio), fechas de primera y última conexión para cada red Wi-Fi conocida."],
    ["¿Qué estándar ISO se enfoca específicamente en asegurar que los métodos y herramientas de investigación forense digital son adecuados para su propósito?", ["ISO 27037 — Directrices para identificación, recolección, adquisición y preservación de evidencia", "ISO 27041 — Directrices para asegurar la idoneidad y adecuación de los métodos de investigación", "ISO 27042 — Directrices para el análisis e interpretación de evidencia digital", "ISO 27043 — Principios y procesos de investigación de incidentes digitales"], 1, "ISO/IEC 27041 proporciona directrices para validar que las herramientas y métodos de investigación forense son aptos para producir resultados confiables y defendibles."],
    ["¿Qué caracteriza al registro de eventos (Event Log) de Windows como fuente de evidencia forense?", ["Es un archivo de texto plano que almacena las políticas de auditoría y configuración de seguridad del sistema", "Es un sistema estructurado de registro de eventos que documenta actividad de seguridad, sistema, aplicaciones y servicios con marcas de tiempo", "Es un log del kernel exclusivo para errores críticos de hardware y controladores con información de depuración", "Es un registro centralizado de conexiones de red que captura IP de origen y destino de cada sesión establecida"], 1, "Los Event Logs de Windows (Security, System, Application y canales especializados) proporcionan información cronológica sobre autenticaciones, cambios de política, errores y actividad del sistema."],
    ["¿Qué tipo de herramienta es más apropiada para capturar la memoria RAM de un sistema Windows que se encuentra encendido?", ["FTK Imager configurado en modo de adquisición de disco físico a través de un bloqueador de escritura", "Herramientas especializadas de volcado de memoria como WinPmem, DumpIt o Magnet RAM Capture", "Wireshark con captura local configurada para interceptar las comunicaciones entre CPU y memoria", "Autopsy con el módulo de adquisición remota habilitado para extraer datos volátiles del sistema"], 1, "Herramientas como WinPmem o DumpIt acceden directamente al espacio de direcciones físico y pueden capturar el contenido completo de la RAM sin reiniciar."],
    ["¿Qué tipo de evidencia crítica puede encontrarse exclusivamente en la memoria volátil (RAM) de un sistema?", ["Shadow copies, puntos de restauración y versiones anteriores de archivos cifrados del sistema", "Procesos en ejecución, conexiones de red activas, claves de cifrado en uso y código inyectado en procesos", "Entradas de la MFT, journal de transacciones NTFS y metadatos de archivos recientemente eliminados", "Registros de arranque UEFI, configuración actual del bootloader y estado de Secure Boot"], 1, "La memoria RAM contiene información efímera invaluable como procesos, hilos, sockets, credenciales y artefactos de malware que desaparecen al apagar el equipo."],
    ["¿Qué diferencia técnica relevante existe entre MD5 y SHA-256 en el contexto de verificación de evidencia forense?", ["MD5 es más adecuado para verificar imágenes de disco completas; SHA-256 se recomienda solo para archivos individuales pequeños", "MD5 genera un digest de 128 bits con colisiones prácticas demostradas; SHA-256 genera 256 bits con mayor resistencia a colisiones", "SHA-256 verifica integridad y autenticidad simultáneamente; MD5 solo verifica integridad sin ninguna propiedad de autenticación", "MD5 requiere una clave secreta para su cómputo; SHA-256 es un algoritmo público que no requiere material criptográfico secreto"], 1, "Aunque MD5 sigue siendo ampliamente usado, sus colisiones prácticas lo hacen cuestionable legalmente; SHA-256 es preferido donde la integridad puede ser disputada."],
    ["¿Qué es un super timeline (timeline forense) y cuál es su propósito en una investigación?", ["Una secuencia de capturas de red ordenadas cronológicamente por protocolo para reconstruir sesiones de comunicación", "Una reconstrucción cronológica unificada de eventos del sistema a partir de múltiples fuentes de artefactos y metadatos", "Un diagrama temporal que representa las relaciones de acceso entre usuarios, grupos y objetos del directorio activo", "Un registro continuo de cambios de integridad generado por el sistema de monitoreo de archivos del endpoint"], 1, "El super timeline combina marcas de tiempo de MFT, registros, logs, prefetch, browsers y otros artefactos en una línea temporal unificada para reconstruir la secuencia de actividad."],
    ["¿Qué precaución específica es prioritaria al manejar un dispositivo móvil que será examinado como evidencia?", ["Conectarlo inmediatamente a un equipo forense mediante cable USB para iniciar la extracción antes de que se agote la batería", "Aislarlo de todas las redes inalámbricas (modo avión, jaula de Faraday) para prevenir borrado remoto o sincronización", "Mantenerlo con conexión de red activa para capturar tráfico de aplicaciones en tiempo real antes de la extracción", "Realizar un respaldo completo a través de iTunes o Android Debug Bridge antes de cualquier otra acción forense"], 1, "El aislamiento de red previene que el dispositivo reciba comandos de borrado remoto (MDM, Find My), sincronice datos con la nube o altere la evidencia mediante actualizaciones."],
    ["¿Qué conjunto de artefactos forenses puede extraerse del análisis de los datos de un navegador web?", ["Únicamente las URLs visitadas, las fechas de acceso y el tamaño de la caché utilizada por cada sitio", "URLs visitadas, marcas de tiempo, historial de descargas, cookies, caché de páginas, términos de búsqueda y formularios completados", "Solo las credenciales almacenadas en el gestor de contraseñas y los certificados SSL aceptados manualmente", "Las direcciones IP resueltas por el navegador, los puertos de conexión utilizados y los certificados del servidor"], 1, "Los artefactos del navegador proporcionan un registro detallado de la actividad web del usuario incluyendo múltiples bases de datos SQLite con historial, descargas, cookies y sesiones."],
    ["¿Cuál es el valor probatorio principal de la documentación fotográfica de una escena con evidencia digital?", ["Sirve como respaldo visual en caso de que los hashes de verificación fallen o sean cuestionados durante el proceso", "Preserva y documenta el estado original de la escena, conexiones físicas y pantallas antes de cualquier manipulación", "Documenta las herramientas forenses y configuraciones utilizadas para cumplir los requisitos de validación de ISO 27041", "Registra las condiciones ambientales como temperatura y humedad que podrían afectar la integridad de los medios magnéticos"], 1, "Las fotografías documentan el estado exacto de la evidencia in situ y pueden ser cruciales para demostrar ante un tribunal que no hubo contaminación de la escena."],
  ],
  dificil: [
    ["Un investigador encuentra que las marcas de tiempo de $STANDARD_INFORMATION muestran una fecha de creación posterior a la de $FILE_NAME para un ejecutable sospechoso en NTFS. ¿Qué indica esta discrepancia?", ["El archivo fue restaurado desde una Volume Shadow Copy, lo cual actualiza $SI pero preserva los valores originales de $FN", "Probable timestomping: se modificó $SI con herramientas de usuario pero $FN fue preservada por el kernel de NTFS", "Una operación de copia entre volúmenes NTFS con diferentes configuraciones de zona horaria causó el desfase temporal", "El archivo fue descomprimido desde un contenedor ZIP que preservó las fechas originales en $FN pero regeneró $SI"], 1, "La discrepancia entre $SI y $FN es un indicador clásico de timestomping porque $FILE_NAME es actualizada exclusivamente por el kernel de NTFS y no es modificable por herramientas de espacio de usuario."],
    ["Para demostrar qué cuentas intentaron autenticarse remotamente en un servidor Windows, ¿qué combinación de log y Event IDs es más relevante?", ["System Log, Event IDs 7045 y 7036 que documentan la instalación e inicio de servicios de acceso remoto", "Security Log, Event IDs 4624 (éxito) y 4625 (fallo) filtrando por Logon Type 3 (red) y 10 (RDP)", "Security Log, Event IDs 4768 y 4769 que registran la emisión de tickets Kerberos TGT y TGS respectivamente", "PowerShell Operational Log, Event IDs 4103 y 4104 que registran comandos ejecutados en sesiones remotas"], 1, "Los eventos 4624 y 4625 del Security Log con Logon Type 3 (red) y 10 (RDP) documentan directamente los intentos de autenticación remota con resultado y cuenta involucrada."],
    ["¿Qué técnica anti-forense a nivel de firmware puede hacer que una imagen forense estándar no capture la totalidad de los sectores del disco?", ["Cifrado transparente del controlador SSD que reescribe los sectores con claves rotativas del firmware", "Manipulación de Host Protected Area (HPA) o Device Configuration Overlay (DCO) que oculta sectores al sistema operativo", "Remapeo dinámico de sectores defectuosos (reallocated sectors) que mueve datos a áreas inaccesibles del disco", "Over-provisioning del SSD que reserva un porcentaje de celdas NAND fuera del espacio direccionable por el host"], 1, "HPA y DCO son configuraciones a nivel de firmware ATA que reducen el espacio visible del disco; una imagen forense estándar solo captura los sectores reportados al sistema operativo."],
    ["Un analista recupera un archivo mediante data carving del espacio no asignado pero carece de nombre y marcas de tiempo del sistema de archivos. ¿Cómo puede establecer contexto temporal para el archivo?", ["Calculando el hash del archivo y buscándolo en bases de datos de archivos conocidos como NSRL para obtener fechas de distribución", "Examinando metadatos internos del archivo (EXIF, propiedades del documento), correlacionando con fragmentos del $UsnJrnl y entradas MFT residuales cercanas", "Analizando la posición física de los sectores en el disco y calculando una fecha aproximada basándose en los patrones de asignación secuencial del sistema de archivos", "Comparando el contenido del archivo con las entradas del $LogFile para identificar la transacción de creación correspondiente y su timestamp"], 1, "Los metadatos embebidos (EXIF, propiedades de documentos), fragmentos del $UsnJrnl y entradas MFT residuales proporcionan contexto temporal independiente del sistema de archivos activo."],
    ["¿Qué artefactos de Windows pueden demostrar que un programa específico fue ejecutado incluso si el ejecutable ya fue eliminado del disco?", ["Los registros de Windows Defender con detecciones históricas y las alertas de AMSI con los scripts interceptados", "Entradas residuales en Prefetch (.pf), Shimcache (AppCompatCache en SYSTEM) y Amcache.hve", "Los Event IDs 4688 del Security Log con la línea de comandos y los Event IDs 1 de Sysmon con el hash del proceso", "Las entradas del Task Scheduler con el historial de ejecución y los registros de la política de restricción de software"], 1, "Prefetch almacena hasta 1024 registros de ejecución con timestamps, Shimcache registra rutas de archivos referenciados por el kernel y Amcache documenta ejecuciones con hashes SHA-1."],
    ["Se sospecha que un atacante usó PowerShell para descargar y ejecutar código malicioso. ¿Dónde debe buscar el investigador las evidencias más directas?", ["En los registros de AMSI con los buffers de scripts analizados y las detecciones de Windows Defender asociadas", "En los logs de Script Block Logging (Event ID 4104), Module Logging del Event Log y el archivo ConsoleHost_history.txt del perfil del usuario", "En las entradas de Prefetch de powershell.exe con las DLLs cargadas y los argumentos de ejecución registrados en Amcache", "En los registros de Sysmon Event ID 1 con los hashes de proceso y Event ID 3 con las conexiones de red del proceso powershell.exe"], 1, "Script Block Logging (4104) registra el contenido completo de scripts ejecutados, Module Logging documenta los módulos importados y ConsoleHost_history.txt guarda un historial de comandos por usuario."],
    ["¿Qué información forense específica proporciona el $UsnJrnl (USN Change Journal) de NTFS?", ["Un mapa completo de los clústeres asignados a cada archivo con sus ubicaciones físicas en el plato del disco", "Un registro cronológico de operaciones sobre archivos y directorios (creación, eliminación, modificación, renombrado) con marcas de tiempo y reason codes", "Un log de transacciones atómicas del sistema de archivos que permite revertir operaciones incompletas y recuperar estados anteriores", "Un índice de los atributos $DATA y $ATTRIBUTE_LIST de cada entrada de la MFT con sus ubicaciones en disco"], 1, "El $UsnJrnl registra cada operación del sistema de archivos con timestamps, reason codes (close, rename, delete, etc.) y referencias a la entrada MFT correspondiente."],
    ["Un servidor comprometido tiene conexiones C2 activas. El equipo forense decide capturar la memoria antes de aislar el equipo de la red. ¿Por qué es crítico mantener este orden?", ["Porque las herramientas de captura de memoria necesitan descargar sus dependencias desde un repositorio de red antes de ejecutarse", "Porque la memoria contiene el estado completo de procesos maliciosos, conexiones activas, credenciales y código inyectado que desaparecería al aislar o apagar", "Porque el aislamiento de red activa mecanismos de autodestrucción programados por el malware que sobrescriben la memoria antes de terminar sus procesos", "Porque la captura de memoria requiere transmitir el volcado a un servidor de recolección remoto para evitar escribir en el disco local comprometido"], 1, "El aislamiento puede terminar procesos, cerrar sockets y liberar páginas de memoria; la captura previa preserva el estado completo de la actividad maliciosa en curso."],
    ["En el contexto de la cadena de custodia, ¿qué diferencia operativa existe entre verificar la evidencia con un hash y verificarla con una firma digital?", ["El hash es más rápido de calcular y adecuado para verificaciones frecuentes; la firma digital se usa solo en la entrega final al tribunal", "El hash demuestra que el contenido no fue alterado; la firma digital además autentica la identidad de quien realizó la verificación y cuándo", "La firma digital solo aplica a documentos e informes del caso; el hash se utiliza exclusivamente para las imágenes forenses de los medios", "El hash proporciona integridad y autenticidad del contenido; la firma digital añade una marca temporal certificada pero no verifica integridad"], 1, "La firma digital vincula el hash a una identidad verificable mediante criptografía asimétrica, proporcionando autenticación y no repudio además de la integridad que ofrece el hash solo."],
    ["Un archivo tiene extensión .jpg pero su encabezado hexadecimal comienza con los bytes 50 4B 03 04 (PK). ¿Qué debe concluir el investigador?", ["El archivo JPEG fue dañado parcialmente y los primeros bytes del encabezado fueron sobrescritos por datos de otro archivo", "La extensión fue alterada deliberadamente: los bytes PK corresponden a un archivo ZIP, DOCX, XLSX u otro contenedor basado en ZIP", "El archivo usa un formato JPEG progresivo empaquetado que utiliza un contenedor ZIP como envoltorio para las capas de resolución", "El disco tiene errores de lectura en los primeros sectores del archivo y los bytes PK son datos residuales del sector anterior"], 1, "La discrepancia entre extensión y magic number (signature de archivo) indica que el archivo fue renombrado deliberadamente para ocultar su verdadera naturaleza."],
    ["¿Cómo puede beneficiar el Volume Shadow Copy Service (VSS) a una investigación forense?", ["VSS replica archivos críticos entre volúmenes locales, proporcionando redundancia que permite comparar versiones para detectar manipulación", "VSS crea instantáneas del volumen en puntos específicos, permitiendo acceder a versiones anteriores de archivos, registro y logs que pudieron ser eliminados", "VSS cifra automáticamente las copias de seguridad del volumen con claves derivadas de BitLocker, protegiendo los datos históricos contra acceso no autorizado", "VSS registra cada operación de escritura en un journal independiente del sistema de archivos, proporcionando un log de cambios más detallado que el $UsnJrnl"], 1, "Las instantáneas VSS preservan el estado del volumen en un momento dado y pueden contener archivos, claves de registro y logs que el atacante eliminó de la versión activa del sistema."],
    ["Según ISO 27042, ¿qué requisitos debe cumplir el análisis de evidencia digital para ser considerado válido en un procedimiento judicial?", ["Debe ser realizado exclusivamente por personal con certificación forense GCFA, EnCE o equivalente reconocida por la jurisdicción", "Debe ser reproducible, estar completamente documentado, basarse en métodos científicamente validados y permitir escrutinio independiente", "Debe utilizar exclusivamente herramientas forenses de código abierto cuyo funcionamiento interno pueda ser auditado y verificado por la contraparte", "Debe incluir un segundo análisis independiente realizado por un perito distinto que confirme los mismos hallazgos con herramientas diferentes"], 1, "ISO 27042 requiere que el análisis sea metódico, reproducible, bien documentado y que los resultados puedan ser sometidos a escrutinio independiente, sin prescribir herramientas o certificaciones específicas."],
    ["¿Qué información forense relevante puede extraerse de la hive SYSTEM del registro de Windows?", ["Historial de navegación, credenciales guardadas, cookies de sesión y certificados SSL aceptados por el usuario", "Nombre del equipo, zona horaria, dispositivos montados (USBSTOR), servicios configurados, interfaces de red y última hora de apagado", "Perfiles de usuario, documentos recientes, rutas de ejecución, programas instalados y asociaciones de tipo de archivo", "Políticas de grupo aplicadas, reglas de firewall de Windows Defender, configuración de BitLocker y claves de recuperación"], 1, "La hive SYSTEM contiene CurrentControlSet con configuración de hardware, servicios (incluyendo USBSTOR), redes, zona horaria (TimeZoneInformation) y el shutdown time."],
    ["Para demostrar que un usuario descargó un archivo específico desde internet, ¿qué combinación de artefactos proporciona la evidencia más completa?", ["Entradas de Prefetch del navegador, timestamps de la MFT y registros de Windows Defender asociados al archivo descargado", "Historial del navegador con la URL, Zone.Identifier (ADS :Zone.Identifier), caché del navegador y marcas de tiempo MACB correlacionadas", "Logs del proxy corporativo con la URL solicitada, registros DNS del resolver local y entradas de Sysmon Event ID 3 con la conexión", "Entradas de auditoría del Event Log con acceso al objeto, hash del archivo en Amcache y registro de la Jump List de la aplicación"], 1, "El Zone.Identifier ADS marca archivos descargados con la URL y zona de seguridad de origen, complementando la evidencia del historial, caché y metadatos del sistema de archivos."],
    ["¿Qué artefactos forenses documentan los mecanismos de persistencia (autostart) configurados en un sistema Windows?", ["Las entradas del Event Log de aplicación que registran los servicios que reportaron inicio exitoso tras cada arranque", "Las claves Run/RunOnce del registro, carpetas de Startup, Scheduled Tasks, servicios y WMI Event Subscriptions", "Los registros de Prefetch que documentan las primeras ejecuciones de cada programa después de cada reinicio del sistema", "Las dependencias declaradas en los manifiestos de aplicación y las entradas del catálogo de componentes de Windows"], 1, "Los mecanismos de persistencia en Windows se encuentran en múltiples ubicaciones: registro (Run, RunOnce, Services), Startup folders, Task Scheduler, WMI, drivers y más."],
    ["Se encuentra un volumen cifrado con BitLocker en un disco incautado. ¿Qué consideración técnica es prioritaria antes de intentar acceder al contenido?", ["Verificar si el TPM del equipo original retiene la clave y puede desbloquear el volumen si se conecta al mismo hardware", "Determinar si existen claves de recuperación (Active Directory, Microsoft Account, archivo de backup) y documentar cada intento en la cadena de custodia", "Crear primero una imagen forense del disco cifrado completo para trabajar sobre la copia y preservar el original intacto", "Intentar montar el volumen en modo solo lectura para verificar si el cifrado fue suspendido y los datos son accesibles sin clave"], 1, "Las claves de recuperación de BitLocker pueden estar almacenadas en AD DS, cuenta Microsoft o como archivo de respaldo; documentar el proceso mantiene la integridad de la investigación."],
    ["Un investigador necesita reconstruir los comandos ejecutados en sesiones cmd.exe de Windows. ¿Qué limitación específica de cmd.exe afecta esta tarea?", ["Cmd.exe no mantiene historial persistente en disco por defecto; los comandos deben buscarse en la memoria RAM, archivo de paginación o en logs de auditoría de procesos", "Cmd.exe almacena el historial en el registro HKCU del usuario pero lo sobrescribe cíclicamente cada 256 comandos por defecto", "Cmd.exe registra los comandos en el Event Log de aplicación pero requiere que la política de auditoría de línea de comandos esté habilitada previamente", "Cmd.exe mantiene un historial en %APPDATA%\\Microsoft\\cmd_history.log pero lo elimina automáticamente al cerrar cada sesión de consola"], 0, "A diferencia de PowerShell (que tiene ConsoleHost_history.txt), cmd.exe no mantiene un historial persistente en disco; los comandos pueden encontrarse en memoria volátil, pagefile o si Process Creation Auditing (4688) está habilitado."],
    ["¿Qué papel cumple el $LogFile de NTFS en una investigación forense y qué tipo de información puede proporcionar?", ["Almacena un índice de los archivos eliminados con sus rutas, marcas de tiempo y posiciones físicas en disco para facilitar la recuperación", "Es el journal de transacciones de NTFS que registra operaciones del sistema de archivos pendientes y completadas, permitiendo reconstruir cambios recientes", "Contiene los checksums de integridad de todos los archivos del volumen que NTFS verifica automáticamente durante las operaciones de lectura", "Guarda las operaciones de cifrado y descifrado realizadas por EFS con las claves de sesión utilizadas para cada archivo protegido"], 1, "El $LogFile registra redo/undo de transacciones NTFS y puede revelar operaciones de creación, modificación y eliminación recientes incluso si los archivos ya no existen en la MFT activa."],
    ["Un sospechoso ejecutó un limpiador de evidencia como CCleaner o BleachBit antes de la incautación del equipo. ¿Qué artefactos podrían sobrevivir a la limpieza?", ["Solo los archivos del sistema operativo protegidos por Windows Resource Protection que no pueden ser eliminados por aplicaciones de usuario", "Registros del $UsnJrnl y $LogFile de NTFS, entradas MFT residuales, Volume Shadow Copies anteriores y fragmentos en espacio no asignado y file slack", "Únicamente los registros del Event Log de seguridad que requieren privilegios de SYSTEM para ser eliminados y están protegidos por ACL", "Solo los archivos que estaban bloqueados por procesos activos al momento de la ejecución del limpiador y no pudieron ser eliminados"], 1, "Los limpiadores operan a nivel de aplicación y rara vez alcanzan journals NTFS ($UsnJrnl, $LogFile), shadow copies no montadas, entradas MFT marcadas como libres o datos en slack space y unallocated space."],
    ["¿Cómo pueden los Alternate Data Streams (ADS) de NTFS ser utilizados como técnica anti-forense?", ["Permiten cifrar archivos individuales con EFS sin que el indicador de cifrado aparezca en las propiedades visibles del archivo", "Permiten almacenar datos ocultos asociados a un archivo en streams adicionales que no son visibles con herramientas estándar del sistema ni alteran su tamaño aparente", "Permiten fragmentar un archivo grande en múltiples streams distribuidos entre diferentes archivos para dificultar su reconstrucción", "Permiten sobrescribir de forma segura el slack space y espacio no asignado asociado a un archivo para eliminar toda traza de contenido anterior"], 1, "Los ADS permiten adjuntar flujos de datos adicionales a cualquier archivo NTFS sin cambiar su tamaño aparente ni ser listados por dir estándar, pudiendo ocultar ejecutables o datos exfiltrados."],
  ],
  extraDificil: [
    ["Un analista de memoria encuentra un proceso svchost.exe (PID 1204) cuyo proceso padre no es services.exe. El proceso tiene regiones VAD con protección PAGE_EXECUTE_READWRITE, contenido que no corresponde a ningún módulo mapeado desde disco y handles abiertos a procesos remotos. ¿Qué combinación específica de hallazgos confirma mejor la hipótesis de inyección?", ["Las regiones VAD muestran PAGE_EXECUTE_READ con contenido que coincide con una DLL legítima de Microsoft cargada mediante side-loading desde una ruta no estándar en %TEMP%", "El PPID anómalo, las regiones VAD con PAGE_EXECUTE_READWRITE sin backing file en disco, la presencia de un PE header en memoria privada y handles cruzados a otros procesos", "El proceso tiene un token de seguridad con SeDebugPrivilege habilitado, múltiples threads activos con afinidad a un solo core y conexiones TCP establecidas a puertos no estándar", "Las páginas del proceso contienen strings codificados en XOR con claves rotativas, el binario en disco difiere del mapeo en memoria y hay hooks en la IAT de ntdll.dll"], 1, "La combinación de PPID incorrecto (no services.exe), regiones ejecutables privadas RWX sin backing file, estructura PE en memoria privada y handles a procesos remotos es el patrón canónico de inyección reflectiva."],
    ["Se investiga un compromiso APT donde el atacante utilizó timestomping en archivos desplegados en NTFS. Si las marcas de $STANDARD_INFORMATION fueron manipuladas, ¿qué combinación de fuentes alternativas construye el timeline más confiable?", ["Marcas de $SI recalculadas con la diferencia de zona horaria del sistema, correlacionadas con alertas de Windows Defender y registros de AMSI", "Marcas de $FILE_NAME (kernel-managed), entradas del $UsnJrnl con reason codes, registros del $LogFile, timestamps de Prefetch y Event IDs 4663/4656 del Security Log", "Metadatos EXIF de imágenes del sistema, timestamps de instantáneas VSS, fechas de puntos de restauración y entradas del catálogo de Windows Update", "Fechas de compilación PE de los ejecutables sospechosos, timestamps de las entradas de Amcache.hve, registros de setupapi.dev.log y logs de instalación MSI"], 1, "Un timeline robusto contra timestomping combina fuentes no manipulables por herramientas de usuario: $FN (kernel-managed), $UsnJrnl, $LogFile y logs de seguridad que documentan acceso a archivos."],
    ["Un disco incautado muestra que la capacidad real reportada por comandos ATA IDENTIFY DEVICE excede el espacio visible para el sistema operativo. ¿Qué técnica anti-forense explica mejor esta discrepancia y cómo se aborda?", ["Una partición OEM oculta del fabricante que contiene la imagen de recuperación del sistema y no es montada por el sistema operativo", "La configuración de una Host Protected Area (HPA) o Device Configuration Overlay (DCO) que reduce el espacio direccionable; se verifica con comandos ATA nativos y herramientas como hdparm", "Una inconsistencia en la tabla de particiones GPT donde el backup header reporta una geometría de disco diferente a la tabla primaria por un error de alineación", "Over-provisioning configurado por el firmware del SSD que reserva un porcentaje de celdas NAND fuera del espacio LBA direccionable para wear leveling y garbage collection"], 1, "HPA y DCO son configuraciones ATA que ocultan sectores al OS; hdparm --dco-identify y --Np pueden revelar y remover estas restricciones para acceder al espacio completo del disco."],
    ["En un análisis de memoria con Volatility se encuentra un proceso con VAD tags VadS y protección PAGE_EXECUTE_READWRITE, conteniendo una estructura PE completa con headers válidos que no corresponde a ningún archivo mapeado en disco. Un thread remoto apunta a esa región. ¿Qué técnica específica describe mejor este patrón?", ["DLL side-loading donde una DLL maliciosa con nombre similar a una legítima fue cargada por el loader de Windows desde una ruta de búsqueda manipulada (DLL search order hijacking)", "Inyección reflectiva de DLL donde el PE fue mapeado manualmente en la memoria del proceso sin utilizar las APIs estándar del loader de Windows (LoadLibrary)", "Atom bombing donde el código fue inyectado mediante la tabla global de átomos de Windows usando QueueUserAPC para ejecutar callbacks en el proceso objetivo", "Early bird injection donde el código fue escrito en la memoria de un proceso creado en estado suspendido y ejecutado antes de que el entry point original tomara control"], 1, "La inyección reflectiva se caracteriza por un PE completo en regiones VAD privadas RWX sin backing file, mapeado manualmente sin pasar por el loader del OS; el thread remoto confirma la ejecución cruzada."],
    ["Según ISO 27043, ¿qué mecanismo del modelo de investigación de incidentes garantiza que todas las actividades de la investigación resistan escrutinio legal y puedan ser auditadas de principio a fin?", ["La fase de preparación previa al incidente donde se establecen y validan los procedimientos operativos estándar y las herramientas forenses", "La fase de análisis donde los resultados son verificados mediante peer review por un segundo examinador forense independiente", "Los procesos concurrentes de documentación continua, gestión de cadena de custodia y aseguramiento de calidad que se ejecutan durante toda la investigación", "La fase de presentación del reporte final donde los hallazgos son revisados por el asesor legal y el examinador antes de la entrega formal"], 2, "ISO 27043 define procesos concurrentes (documentation, chain of custody management, quality assurance) que deben mantenerse activos durante todas las fases para asegurar auditabilidad y admisibilidad."],
    ["Un atacante usó NTFS Transactional (TxF) para crear, utilizar y eliminar archivos maliciosos dentro de una transacción que luego fue revertida intencionalmente. ¿Dónde pueden quedar artefactos residuales de esta actividad?", ["En las entradas de la MFT que fueron marcadas como libres pero conservan los atributos $SI y $FN del archivo creado dentro de la transacción revertida", "En el Common Log File System (CLFS) que registra las operaciones transaccionales, en la memoria volátil si el sistema no fue reiniciado y potencialmente en el $UsnJrnl", "En las shadow copies del volumen anteriores a la transacción que conservan un snapshot del estado previo del sistema de archivos", "En los registros de auditoría del Event Log de seguridad que documentan las operaciones de archivo independientemente de si la transacción fue confirmada o revertida"], 1, "Las transacciones NTFS revertidas pueden dejar artefactos en el log CLFS del motor transaccional (TxF) y en memoria; además, el $UsnJrnl puede registrar operaciones previas al rollback."],
    ["Se analiza un dump de memoria de un servidor Linux comprometido que muestra hooks en la tabla de syscalls del kernel y módulos cargados no reconocidos. ¿Qué análisis diferencia un rootkit LKM de una modificación administrativa legítima del kernel?", ["Verificar si los módulos fueron cargados con insmod o modprobe examinando los logs de dmesg y si aparecen mensajes de inicialización estándar del módulo", "Verificar firmas de módulos contra las claves del sistema, comparar la syscall table con los símbolos conocidos del kernel, buscar discrepancias en las listas de procesos (task_struct walk vs /proc) y comprobar con imagen limpia", "Analizar las fechas de compilación de los archivos .ko y compararlas con la fecha de instalación del kernel y el historial de actualizaciones del gestor de paquetes", "Examinar los permisos y propietarios de los archivos de módulos en /lib/modules y verificar que coinciden con los del paquete original del kernel distribuido"], 1, "Un rootkit LKM se diferencia por hooks no documentados en syscalls, ausencia de firma válida del kernel, discrepancias entre walks de task_struct y /proc (ocultación de procesos) y contenido que no coincide con distribuciones limpias."],
    ["En una investigación de ransomware se recupera material criptográfico parcial de la memoria RAM del sistema afectado. ¿Qué consideración técnica es más crítica para determinar si es posible el descifrado de los archivos?", ["Determinar si la clave fue generada localmente por el ransomware o recibida del servidor C2 para establecer si el material recuperado es la clave completa o solo un derivado parcial", "Identificar el algoritmo exacto (AES, ChaCha20, etc.), el modo de operación (CBC, CTR, GCM), el esquema de derivación de clave y determinar si el material en memoria es la clave de sesión, la KEK o un estado intermedio del key schedule", "Verificar si el ransomware utilizó cifrado híbrido (simétrico + asimétrico) para seleccionar si se necesita la clave privada RSA del atacante o la clave simétrica de sesión", "Comprobar si el material criptográfico encontrado corresponde al cifrado de los archivos del usuario o al cifrado del propio binario del ransomware usado como capa de protección"], 1, "Sin identificar correctamente algoritmo, modo, IV/nonce y la naturaleza exacta del material (session key, KEK, expanded key schedule), el descifrado producirá resultados incorrectos incluso con material parcialmente válido."],
    ["Un forense de red documenta una exfiltración mediante túnel DNS con subdominios de alta entropía codificados en base32 hacia un dominio controlado por el atacante. ¿Qué combinación de evidencia construye el caso más sólido?", ["Logs del servidor DNS recursivo corporativo con las consultas resueltas, registros WHOIS y pasivo DNS del dominio C2, y capturas de tráfico del firewall perimetral con los flujos UDP/53", "PCAPs con las consultas y respuestas DNS completas, correlación temporal con procesos del host (Sysmon Event ID 22), análisis estadístico del volumen y entropía, y decodificación del payload exfiltrado", "Registros de NetFlow con los flujos UDP/53 hacia el servidor autoritativo del dominio C2, logs del proxy DNS con las consultas denegadas y alertas del IDS con las firmas DNS-tunnel activadas", "Capturas de las consultas DNS en formato PCAP-NG, correlación con las reglas de detección del SIEM basadas en longitud de subdominios y registros de threat intelligence del dominio C2"], 1, "La documentación completa requiere PCAP (evidencia de red), correlación con el host generador (Sysmon 22), análisis estadístico (entropía, volumen anómalo) y decodificación del contenido para demostrar qué datos fueron exfiltrados."],
    ["Se sospecha que un atacante configuró WMI Event Subscriptions como mecanismo de persistencia en un sistema Windows comprometido. ¿Dónde debe buscar el investigador y qué artefactos son más específicos para esta técnica?", ["En las claves Run/RunOnce del registro y las Scheduled Tasks del Task Scheduler que fueron creadas programáticamente mediante WMI como API intermediaria", "En el repositorio WMI (OBJECTS.DATA en %SystemRoot%\\System32\\wbem), logs de WMI-Activity del Event Log, y Sysmon Event IDs 19/20/21 buscando instancias de __EventFilter, __EventConsumer y __FilterToConsumerBinding", "En los scripts de inicio del Group Policy Object (GPO) que fueron desplegados a través de filtros WMI asociados a las políticas del dominio de Active Directory", "En las entradas de Amcache y Shimcache que registran los binarios ejecutados como procesos hijos de wmiprvse.exe (WMI Provider Host) con sus timestamps de ejecución"], 1, "Las WMI Event Subscriptions persisten en el repositorio WMI (OBJECTS.DATA) como objetos __EventFilter/__EventConsumer/__FilterToConsumerBinding; Sysmon 19-21 y WMI-Activity los detectan específicamente."],
    ["Un disco SSD con TRIM habilitado fue entregado como evidencia. El investigador nota que archivos eliminados hace varios días no pueden recuperarse mediante data carving del espacio no asignado. ¿Qué mecanismo técnico del SSD explica esta situación?", ["El controlador del SSD implementa cifrado transparente (SED) y al eliminar un archivo destruye la clave de cifrado específica del bloque correspondiente, haciendo los datos irrecuperables", "El comando TRIM notificó al controlador que los bloques LBA están libres, permitiendo al garbage collector del firmware sobrescribirlos internamente de forma irreversible durante las operaciones de mantenimiento", "El proceso de wear leveling del SSD redistribuyó proactivamente los datos válidos a bloques nuevos y sobrescribió las ubicaciones originales con datos de nivelación de desgaste", "El firmware del SSD compactó los bloques con datos válidos durante la idle garbage collection y reinicializó eléctricamente las celdas NAND de los bloques sin datos válidos"], 1, "TRIM informa al controlador SSD que los bloques lógicos están libres; el garbage collector interno puede borrar esas celdas NAND en cualquier momento posterior, haciendo los datos irrecuperables a diferencia de un HDD."],
    ["Se investiga un ataque Golden Ticket en Active Directory. ¿Qué hallazgo específico en los logs de eventos de un controlador de dominio es un indicador fuerte de este ataque?", ["Event ID 4771 con código de fallo 0x18 (pre-authentication failed) en múltiples cuentas privilegiadas indicando ataques de fuerza bruta contra el hash de KRBTGT", "Event ID 4769 (TGS request) con tipo de cifrado RC4-HMAC (0x17) para servicios que deberían usar AES, combinado con ausencia de un Event ID 4768 (TGT request) previo correspondiente", "Event ID 4776 con código de error 0xC000006A indicando validaciones NTLM fallidas desde estaciones que deberían usar exclusivamente autenticación Kerberos", "Event ID 4672 con asignación inesperada de SeDebugPrivilege y SeImpersonatePrivilege a cuentas de servicio que normalmente operan con privilegios restringidos"], 1, "Los Golden Tickets forjados suelen usar cifrado RC4 (más simple de generar con el hash NTLM de KRBTGT); un TGS sin TGT previo indica que el ticket fue creado offline sin pasar por el KDC."],
    ["En el análisis forense de un compromiso cloud en AWS, se descubre que el atacante usó credenciales temporales STS (AssumeRole) para acceder a buckets S3. ¿Qué fuentes de log son necesarias para reconstruir la cadena completa de acceso?", ["Los logs de acceso del bucket S3 (server access logging), los VPC Flow Logs del tráfico hacia los endpoints S3 y las métricas de CloudWatch con las operaciones GetObject/PutObject", "CloudTrail para las llamadas AssumeRole y GetSessionToken con el ARN de la sesión temporal, los S3 access logs con el ARN de sesión correlacionado y la trazabilidad del source IP con otros IOCs", "Los registros de AWS Config que documentan cambios en las políticas del bucket, el historial de hallazgos de IAM Access Analyzer y las alertas de GuardDuty asociadas al acceso anómalo", "Los logs de AWS Organizations con los eventos de acceso cross-account, los registros de AWS SSO con las sesiones federadas y el CloudTrail organizacional con los eventos de administración"], 1, "La reconstrucción requiere: CloudTrail para trazar la generación de credenciales temporales (AssumeRole/GetSessionToken), S3 access logs para correlacionar el ARN de sesión con operaciones específicas y análisis del source IP."],
    ["Un atacante utilizó la técnica BYOVD (Bring Your Own Vulnerable Driver) cargando un driver legítimo firmado con una vulnerabilidad conocida para deshabilitar el EDR. ¿Qué evidencia forense documenta específicamente esta técnica?", ["Las alertas del EDR generadas antes de su desactivación que identifican el driver vulnerable, combinadas con los logs de Code Integrity que documentan la carga de drivers firmados", "La carga del driver (System Log Event IDs 7045/7036), la correlación temporal con la desactivación del EDR, la firma digital válida del driver y la coincidencia de su hash con bases de datos de drivers vulnerables conocidos (LOLDrivers)", "Los registros de integridad de código (Code Integrity) con las verificaciones de firma, los dumps de crash del proceso del EDR y los logs de Windows Update mostrando la instalación del driver", "Las entradas de Autoruns que muestran el driver registrado como servicio del kernel, los registros de Device Manager con los detalles de instalación del dispositivo y los logs de PnP del sistema"], 1, "BYOVD se evidencia por: instalación de un servicio de driver (7045), hash que coincide con listas como LOLDrivers, firma digital válida (no es malware per se) y correlación temporal con la caída o deshabilitación del EDR."],
    ["¿Qué desafío forense específico presentan los contenedores Docker efímeros en comparación con un sistema operativo tradicional y cómo se aborda?", ["Los contenedores comparten el kernel del host, impidiendo diferenciar artefactos del contenedor de los del sistema anfitrión sin correlacionar namespaces de PID y montajes del filesystem", "Los contenedores usan capas de overlay filesystem donde los cambios se pierden al destruir el contenedor; se requiere capturar el writable layer (upperdir), analizar las capas de la imagen, los logs del daemon y correlacionar con el host", "Los contenedores cifran su almacenamiento efímero por defecto usando dm-crypt con claves derivadas del ID del contenedor, impidiendo acceder a los datos sin la clave del runtime", "Los contenedores operan con network namespaces aislados que impiden correlacionar su actividad de red con los logs del host sin acceso directo a la configuración del container runtime"], 1, "La naturaleza efímera del writable layer de overlay2 requiere capturar el upperdir antes de destruir el contenedor; el análisis completo necesita capas de imagen, logs del daemon/orchestrator y correlación con el kernel del host."],
    ["Se investiga una exfiltración donde el sospechoso utilizó steganografía LSB en imágenes JPEG publicadas en redes sociales. ¿Qué enfoque de análisis forense es más efectivo para detectar esta técnica?", ["Comparación visual automatizada pixel a pixel entre la imagen publicada y la imagen original (si está disponible) para identificar regiones con variaciones cromáticas estadísticamente significativas", "Análisis estadístico de la distribución de coeficientes DCT, test chi-cuadrado sobre los patrones LSB, detección de herramientas de steganografía en artefactos del sistema y análisis de anomalías en la estructura JFIF/EXIF", "Extracción y comparación de los metadatos EXIF entre la imagen original y la publicada para detectar indicadores de procesamiento posterior incompatibles con el software de edición declarado", "Verificación del hash de la imagen publicada contra la original para confirmar modificación, seguida de sustracción de imágenes para aislar y analizar el payload embebido en los bits menos significativos"], 1, "La steganografía LSB en JPEG altera patrones estadísticos de los coeficientes DCT detectables mediante análisis chi-cuadrado y RS analysis; los artefactos de herramientas stego (OpenStego, Steghide) en el sistema del sospechoso complementan la evidencia."],
    ["Un investigador debe presentar evidencia digital en un procedimiento judicial. Según las directrices de ISO 27037 e ISO 27042, ¿qué elementos son imprescindibles para que la evidencia sea admisible y defendible?", ["Informe técnico firmado digitalmente por un perito con certificación vigente, acompañado de capturas de pantalla anotadas de los hallazgos principales y una declaración jurada sobre la metodología utilizada", "Documentación completa de la cadena de custodia con firmas, hashes pre y post-análisis, descripción reproducible del método, validación de herramientas utilizadas e informe que distinga hechos observados de opiniones del perito", "Imagen forense verificada con doble hash (MD5 + SHA-256), informe automatizado generado por la suite forense utilizada y acreditación vigente del laboratorio según ISO 17025 o equivalente", "Acta de incautación firmada por autoridad competente, copia certificada de la imagen forense en formato E01, testimonio del primer respondedor documentando el estado de la escena y peritaje de la contraparte"], 1, "La admisibilidad según ISO 27037/27042 requiere: integridad verificable (hashes), cadena de custodia documentada, método reproducible, herramientas validadas (ISO 27041) y separación clara entre observaciones factuales e interpretaciones del perito."],
    ["Se detecta que un atacante desplegó un bootkit UEFI que persiste a través de reinstalaciones del sistema operativo. ¿Qué análisis forense específico se requiere para investigar esta amenaza?", ["Analizar el firmware del disco duro buscando modificaciones en el controlador SATA y comparar el contenido del firmware con la versión original publicada por el fabricante del disco", "Examinar la EFI System Partition (ESP), verificar la integridad de los binarios de arranque (.efi) contra hashes conocidos, analizar las variables NVRAM del firmware e inspeccionar los logs de Secure Boot y las DBX", "Extraer y desensamblar el Master Boot Record (MBR) y el Volume Boot Record (VBR) para identificar hooks de arranque que redirigen la ejecución antes de que el bootloader UEFI tome control", "Realizar un análisis del chip SPI flash mediante hardware JTAG o SPI reader para extraer y verificar la integridad de las rutinas de inicialización del firmware UEFI contra la imagen original"], 1, "Los bootkits UEFI se alojan típicamente en la ESP (modificando binarios .efi) o en variables NVRAM; la verificación de Secure Boot DBX, hashes de bootloaders y análisis de la ESP son el enfoque estándar de investigación."],
    ["En un caso de insider threat, se necesita demostrar forense que un empleado conectó un dispositivo USB específico y copió archivos confidenciales en una fecha determinada. ¿Qué constelación de artefactos Windows proporciona la evidencia más sólida y atribuible?", ["Registros de la solución DLP corporativa con la operación de copia detectada, logs del servidor de archivos con los accesos a los documentos y el reporte de auditoría de Active Directory con los eventos de la cuenta", "Entradas de USBSTOR con VID/PID y número de serial, setupapi.dev.log con timestamp de primera instalación, Event IDs 20001/20003, shellbags mostrando navegación en la unidad USB y archivos LNK o Jump Lists con timestamps apuntando a la letra asignada", "Event IDs 4663 del Security Log con acceso a los objetos de archivo, Event IDs 4656 con los handles solicitados, Sysmon Event IDs 11 con la creación de archivos en el medio removible y registros del antivirus corporativo", "Logs de Microsoft Endpoint Manager con el registro del dispositivo, registros de BitLocker To Go con el cifrado del medio removible y entradas de Windows Information Protection con la clasificación de los datos copiados"], 1, "USBSTOR (VID/PID/serial), setupapi.dev.log (timestamps de instalación del driver), shellbags (evidencia de navegación en la unidad) y LNK/Jump Lists (timestamps de acceso a archivos en la letra del USB) proporcionan una línea temporal completa."],
    ["Un analista forense recibe un volcado de memoria de 64 GB de un servidor comprometido, pero el perfil del kernel no coincide con ningún perfil estándar de Volatility y sospecha que las estructuras del kernel fueron manipuladas. ¿Qué enfoque alternativo permite avanzar en el análisis?", ["Utilizar Rekall como framework alternativo que puede inferir automáticamente el perfil del kernel escaneando las estructuras KDBG y KPCR directamente desde el volcado de memoria", "Generar un perfil personalizado compilando el módulo de debug del kernel exacto del sistema, complementar con escaneo YARA independiente de estructuras del OS, búsqueda de patrones de red (IPs, URLs) y data carving de PE/ELF directamente en el dump", "Convertir el volcado de memoria a formato raw y analizarlo como imagen de disco para recuperar archivos y artefactos de sistema de archivos usando herramientas de file carving convencionales como Scalpel o PhotoRec", "Extraer las estructuras EPROCESS manualmente desde offsets conocidos de la versión de kernel más cercana disponible y ajustar las diferencias de offset de forma incremental hasta localizar la lista de procesos activos"], 1, "Cuando las estructuras del kernel están manipuladas: generar un perfil personalizado (dwarf2json/volatility3), complementar con YARA rules (malware signatures independientes del OS), grep de IOCs de red y PE carving permiten extraer evidencia sin depender de la integridad del kernel."],
  ],
};
